function renderCreateOrder({root,params,session},s){
 const available=s.quotes.filter(q=>q.status==='Aprobada'&&(!realMode||q.approval)&&!s.orders.some(o=>o.quoteId===q.id)),selected=params.get('cotizacion')||'',q=available.find(q=>q.id===selected),context=q?getContext(s,{quoteId:q.id}):{};
 root.innerHTML=pageHeader('Nueva orden de trabajo','Selecciona una cotización aprobada y asigna el personal responsable.')+form('DATOS DE LA ORDEN',select('Cotización aprobada (obligatoria)','quoteId',realMode?[placeholder()]:selectOptions(available,q=>{const c=getContext(s,{quoteId:q.id});return `${q.id} / ${c.client?.name} / ${c.vehicle?.plate} — Aprobada`;}),q?.id||'','required')+field('Cliente (solo lectura)','client',context.client?.name||'','text','readonly')+field('Vehículo (solo lectura)','vehicle',context.vehicle?vehicleLabel(context.vehicle):'','text','readonly')+textarea('Trabajos autorizados (derivados de la cotización, solo lectura)','work',q?.items.map(i=>`${i.concept} · ${i.type} · Cant. ${i.quantity}`).join('\n')||'','readonly')+select('Mecánico responsable','mechanicId',mechOptions(s),'','required')+select('Auxiliar (opcional)','assistantId',auxOptions(s),'')+hint('Estado inicial: Pendiente. El código de OT y la fecha se generan automáticamente.'),submit('Crear orden')+link('Volver al listado','ordenes'));
 if(realMode)remotePicker(root.querySelector('[name=quoteId]'),{selectedId:q?.id||'',initialLabel:q?q.id+' · '+(q.clientName||'Cliente'):'' ,label:q=>q.id+' · '+(q.clientName||'Cliente'),search:lookupApprovedQuotes,onSelect:q=>go('ordenes/nueva?cotizacion='+q.id)});else root.querySelector('[name="quoteId"]').onchange=ev=>go('ordenes/nueva?cotizacion='+ev.target.value);
 bindForm('edit-form',async data=>{const order=await createOrder(data,session.id);notify(`${order.id} creada en estado Pendiente.`);go('ordenes/editar/'+order.id);});
 if(!available.length)root.insertAdjacentHTML('beforeend',hint('No hay cotizaciones aprobadas sin orden. Guarda y aprueba una cotización para continuar.'));
}
function renderUpdateOrder({root,path,session},s,canAssign=true){
 const order=s.orders.find(o=>o.id===path[2]);if(!order)throw new Error('No se encontró la orden de trabajo.');const c=getContext(s,order),closed=Boolean(order.delivery)||order.state==='Cancelada'||(realMode&&order.state==='Finalizada');
 root.innerHTML=pageHeader('Actualizar orden de trabajo','Modifica el personal y estado; registra cada avance sin sobrescribir los anteriores.',badge(order.state)+(order.delivery?badge('Entregado'):''))+form('DATOS DE LA ORDEN',field('N.º de OT (solo lectura)','code',order.code||order.id,'text','readonly')+field('Cliente (solo lectura)','client',c.client?.name,'text','readonly')+field('Vehículo / placa (solo lectura)','vehicle',c.vehicle?vehicleLabel(c.vehicle):'','text','readonly')+field('Resumen de atención (solo lectura)','diagnosis',c.diagnosis?.findings||c.reception?.symptoms,'text','readonly')+select('Mecánico responsable','mechanicId',mechOptions(s),order.mechanicId,closed||!canAssign?'disabled':'required')+select('Auxiliar asignado','assistantId',auxOptions(s),order.assistantId,closed||!canAssign?'disabled':'')+select('Estado de la orden','state',ORDER_STATES,order.state,closed?'disabled':'required')+field('Fecha de creación (solo lectura)','createdAt',date(order.createdAt),'text','readonly')+textarea('Observación / avance de esta actualización','note','',closed?'disabled':'required maxlength="4000" placeholder="Describe únicamente el avance nuevo…"')+field('Prueba realizada (opcional para guardar avances)','test','','text',closed?'disabled':'maxlength="100" placeholder="Ej. Prueba de ruta"')+select('Resultado de prueba','result',['No aplica','Satisfactoria','Fallida'],'No aplica',closed?'disabled':''),submit('Guardar cambios')+link('Volver al listado','ordenes')+`<button type="submit" class="secondary-button" value="finalize">Finalizar orden</button>`);
 if(closed)root.insertAdjacentHTML('beforeend',hint(order.delivery?'Vehículo entregado: la orden y su historial están cerrados.':order.state==='Finalizada'?'Orden finalizada: los avances y pruebas se conservan sin sobrescribir. Puedes continuar en Pagos y entrega.':'Orden cancelada: se conserva su historial.'));
 if(!canAssign&&!closed)root.insertAdjacentHTML('beforeend',hint('La asignación de personal requiere el permiso de reasignar mecánicos. Puedes guardar avances si tu rol lo permite.'));
 if(realMode){root.querySelector('#edit-form .form-actions')?.insertAdjacentHTML('beforeend','<button type="button" class="secondary-button" id="technical-control">Control técnico · Ficha</button>');const b=root.querySelector('#technical-control');if(b)b.onclick=()=>openInspection(order,c.quote).catch(error=>showModal('Control técnico',hint(error.message)));}
 if(closed)root.querySelectorAll('[type="submit"]').forEach(b=>b.disabled=true);
 else bindForm('edit-form',async (data,action)=>{await updateOrder(order.id,{...data,mechanicId:canAssign?data.mechanicId:order.mechanicId,assistantId:canAssign?data.assistantId:order.assistantId,state:action==='finalize'?'Finalizada':data.state},session.id);notify('Avance guardado en el historial de la orden.');go('ordenes/editar/'+order.id);});
 root.insertAdjacentHTML('beforeend',hint('Puedes guardar avances sin prueba. Para finalizar se exige una prueba satisfactoria vigente, registrada después de la última reparación; puedes usar una ya guardada o registrarla en esta actualización.'));
 root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">HISTORIAL DE AVANCES Y PRUEBAS</h2>${table(['Fecha y hora','Usuario','Avance','Prueba','Resultado','Estado'],order.updates.slice().reverse().map(u=>[stamp(u.at),e(s.users.find(x=>x.id===u.by)?.name||u.by),e(u.note),e(u.test||'—'),e(u.result),badge(u.state)]),'Todavía no se registran avances para esta orden.')}</section>`);
}
function askDeleteOrder(id){confirmDelete({title:`¿Eliminar orden ${id}?`,message:`Vas a eliminar definitivamente la orden <strong>${e(id)}</strong>.`,onConfirm:async()=>{await deleteOrder(id);notify('Orden eliminada.');go('ordenes');}});}
export async function renderRescues({root,path,session}){
 const s=getStore();if(path[1]==='tareas'){renderTasks({root,session},s);return;}
 root.innerHTML=pageHeader('Nuevo auxilio mecánico','Registro de atención fuera del taller',link('Mis tareas · vista auxiliar','auxilio/tareas'))+form('SOLICITUD DE AUXILIO',select('Cliente','clientId',selectOptions(s.clients,clientLabel),'','required')+select('Vehículo','vehicleId',[placeholder('Seleccione cliente primero')],'','required')+field('Ubicación reportada','location','','text','required maxlength="300" placeholder="Distrito, dirección o referencia"')+select('Tipo de incidente','incident',['Falla mecánica','Vehículo inmovilizado','Otro'])+select('Unidad de auxilio','unit',realMode?selectOptions(s.units,u=>u.code+' · '+(u.description||'')):[placeholder(),'Unidad 01','Unidad 02'],'','required')+textarea('Descripción del problema','description','','required maxlength="4000"')+select('Técnico asignado','technicianId',mechOptions(s),'','required'),submit('Registrar auxilio'));
 if(realMode){
  const canCreate=permissionChecker(session.role)('auxilio','crear');
  root.querySelector('[name="unit"]').closest('.form-field').insertAdjacentHTML('beforeend',`${s.units.length?'':'<p class="cell-note" data-unit-empty role="status">No hay unidades de auxilio registradas. Una unidad es el vehículo/equipo móvil que atiende una solicitud.</p>'}${canCreate?'<button type="button" class="secondary-button" id="new-unit">+ Registrar unidad</button>':''}`);
  if(canCreate)root.querySelector('#new-unit').onclick=()=>{const dialog=showModal('Registrar unidad de auxilio',form('UNIDAD REAL',field('Código de la unidad','code','','text','required maxlength="30"')+field('Descripción (opcional)','description','','text','maxlength="150"'),submit('Guardar unidad')+button('Cancelar','cancel'),'unit-form'));dialog.querySelector('[data-action=cancel]').onclick=()=>dialog.close();bindForm('unit-form',async data=>{const unit=await saveUnit(data);s.units.push(unit);root.querySelector('[data-unit-empty]')?.remove();const select=root.querySelector('[name=unit]');select.insertAdjacentHTML('beforeend',`<option value="${e(unit.id)}">${e(unit.code+' · '+(unit.description||''))}</option>`);select.value=unit.id;dialog.close();notify('Unidad de auxilio registrada.');});};
 }
 root.querySelector('[name="clientId"]').onchange=ev=>root.querySelector('[name="vehicleId"]').innerHTML=selectOptions(s.vehicles.filter(v=>v.clientId===ev.target.value),vehicleLabel).map(o=>`<option value="${e(o.value)}">${e(o.label)}</option>`).join('');
 if(realMode){await clientPicker(root,'auxilio');await ownerVehicles(root,'auxilio',s);}
 if(!root.isConnected)return;
 bindForm('edit-form',async data=>{const a=await saveRescue(data,session.id);notify(`Auxilio ${a.id} registrado.`);go('auxilio');});
 root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">AUXILIOS REGISTRADOS</h2>${table(['Solicitud','Fecha','Cliente','Vehículo','Ubicación','Técnico'],s.rescues.slice().reverse().map(a=>[e(a.id),date(a.createdAt),e(s.clients.find(c=>c.id===a.clientId)?.name||a.clientName),e(s.vehicles.find(v=>v.id===a.vehicleId)?.plate||a.vehiclePlate),e(a.location),e(s.users.find(u=>u.id===a.technicianId)?.name||a.technicianName)]))}</section>`);
}
function renderTasks({root,session},s){
 const isAux=realMode||session.role==='Auxiliar',kevin=isAux?session.id:'u-kevin',name=s.users.find(u=>u.id===kevin)?.name||session.name;
 const orders=realMode?s.tasks||[]:s.orders.filter(o=>o.assistantId===kevin&&ACTIVE_STATES.includes(o.state));
 root.innerHTML=pageHeader(`Hola, ${name}`,'Mis tareas · órdenes asignadas',link('Volver a Auxilio mecánico','auxilio'))+`<div class="task-grid">${orders.map(o=>{const c=getContext(s,o);return `<article class="panel task-card"><div class="task-heading"><span class="task-order">${e(o.id)}</span>${badge(o.state)}</div><h2>${e(c.vehicle?.brand)} ${e(c.vehicle?.model)} · ${e(c.vehicle?.plate)}</h2><p>${e(c.quote?.items.filter(i=>i.type==='Servicio').map(i=>i.concept).join(', '))}</p><button type="button" class="primary-button" data-task="${e(o.id)}" ${realMode&&!permissionChecker(session.role)('ordenes','editar')?'disabled title="Se requiere ordenes.editar"':''}>Actualizar estado ${icon('arrow')}</button></article>`;}).join('')||'<section class="panel"><p>No hay tareas activas asignadas.</p></section>'}</div>`;
 root.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const o=orders.find(o=>o.id===b.dataset.task);const dialog=showModal('Actualizar estado · '+o.id,form('REGISTRAR AVANCE',select('Estado de la orden','state',['Pendiente','En reparación','En pruebas'],o.state,'required')+textarea('Observación / avance','note','','required maxlength="4000"'),submit('Guardar cambios')+button('Cancelar','cancel'),'task-form'));dialog.querySelector('[data-action="cancel"]').onclick=()=>dialog.close();bindForm('task-form',async data=>{await updateOrder(o.id,{...data,mechanicId:o.mechanicId,assistantId:o.assistantId,result:'No aplica',test:''},session.id);dialog.close();notify('Estado actualizado.');go('auxilio/tareas');});});
}
